def right_angle_triangle(a, b, c):
    # Check if any of the sides are less than or equal to zero
    if a <= 0 or b <= 0 or c <= 0:
        return False

    # Check if any side is greater than or equal to the sum of the other two sides
    if a >= b + c or b >= a + c or c >= a + b:
        return False

    # Check if the sides satisfy the Pythagorean theorem
    return a**2 + b**2 == c**2

